-- 0026: Add NKHS tree measurement PWA and replace conceptual covers with live application screenshots.
INSERT OR REPLACE INTO projects (id, zh, en, sort_order) VALUES ('job-radar', '{"id":"job-radar","category":"大學校外作品","title":"Job Radar — 個人化求職雷達","period":"2026","description":"每天整理 104、Cake 與 LinkedIn 的職缺，依我的技能和條件排序，附上推薦理由。清單每日更新，可按來源、職類與搜尋字詞篩選。","tags":["Python","Playwright","Cloudflare Pages","GitHub Actions","靜態生成"],"detail":{"purpose":"我想把不同求職網站的職缺放在同一張清單裡，比較條件時不用一直切換頁面。","concept":"工具從三個來源整理職缺，保留原始連結，再依技能和求職條件排序。公開頁面只顯示職缺與篩選功能；個人化分析留在私有資料中。","outcome":"Job Radar 每日更新職缺清單，讓我先查看較符合條件的職缺，再自行確認職務內容與申請狀態。","tech":[{"group":"爬蟲與聚合","items":[{"name":"104 API 逆向","desc":"舊版 joblist API 失效、公司頁為 SPA，逆向前端 bundle 找出現行 /api/companies/{code}/jobs 端點與代碼編碼規則"},{"name":"多來源整合","desc":"整理 104、Cake 與 LinkedIn 職缺，轉成一致的欄位格式。"}]},{"group":"評分與呈現","items":[{"name":"個人化評分引擎","desc":"公司適配度×關鍵字×地點×經歷×新人友善多維加權，權重外置可調；階段分桶感知畢業時程"},{"name":"靜態生成 RWD","desc":"建置時靜態渲染單檔 HTML，前端僅做過濾；桌機多欄、手機單欄；Medium 閱讀風排版"}]},{"group":"自動化與安全","items":[{"name":"雲端 CI/CD","desc":"GitHub Actions 每日 cron 爬取→建置→wrangler 部署 Cloudflare Pages，電腦關機照跑"},{"name":"伺服器端登入保護","desc":"Pages Function（_worker.js）密碼保護私密分析頁，未驗證者資料不傳輸、失敗關閉"}]}],"demo":"https://job-radar-bck.pages.dev","github":"https://github.com/Jcsk7049/job-radar","images":[{"src":"/images/job-radar/cover.png","caption":"Cloudflare Pages 正式版求職看板實際運動畫面。"}]},"cover":"/images/job-radar/cover.png"}', '{"id":"job-radar","category":"大學校外作品","title":"Job Radar: Personalized Job Search Dashboard","period":"2026 – Present","description":"A daily list of roles from 104, Cake, and LinkedIn, ranked against my skills and criteria with a reason for each recommendation. Filter by source, role, or search term.","tags":["Python","Playwright","Web Scraping","GitHub Actions","Cloudflare Pages"],"detail":{"purpose":"I wanted one place to compare listings across job sites without switching between pages.","concept":"The tool collects roles from three sources, keeps the original links, and ranks them against my criteria. The public page shows listings and filters; personal analysis stays private.","outcome":"Job Radar refreshes the list daily. I review the suggested roles and verify each position and application status myself.","tech":[{"group":"Data Collection","items":[{"name":"104 API reverse engineering","desc":"After the old joblist API was discontinued, found the current /api/companies/{code}/jobs endpoint and company-code scheme from the company-page SPA''s frontend bundle, pulling all listings instead of keyword search"},{"name":"Playwright dynamic rendering","desc":"Cake''s job pages are JS-rendered, so I use a headless browser and wait for content to load before scraping"},{"name":"LinkedIn guest endpoint","desc":"Uses LinkedIn''s public guest job API (plain HTTP) to avoid the login wall and typical scraper blocks"}]},{"group":"Scoring & Presentation","items":[{"name":"Externalized scoring engine","desc":"Company fit, title keywords, location, experience thresholds, etc. all live in config.json, so ranking changes don''t require code edits"},{"name":"Static dashboard generation","desc":"build_dashboard.py normalizes the three sources'' JSON into one card schema and renders a single responsive HTML file; frontend JS only handles filtering/search/saved status (localStorage)"}]},{"group":"Automation & Deployment","items":[{"name":"GitHub Actions cron","desc":"A daily cron runs the full pipeline (scrape -> score -> build -> deploy); migrated from a local Windows scheduled task so it still runs with the computer off"},{"name":"CI deploy debugging","desc":"A Cloudflare deploy token with invisible characters was breaking request headers; fixed by stripping non-printable characters with tr -cd before deploy and printing the string length to diagnose"}]}],"demo":"https://job-radar-bck.pages.dev","github":"https://github.com/Jcsk7049/job-radar","images":[{"src":"/images/job-radar/cover.png","caption":"Live Job Radar dashboard on Cloudflare Pages, captured in the browser."}]},"cover":"/images/job-radar/cover.png"}', '0');
INSERT OR REPLACE INTO projects (id, zh, en, sort_order) VALUES ('analog-ic-studio', '{"id":"analog-ic-studio","category":"大學校外作品","title":"Analog IC Studio — 類比 IC 自動調參平台","period":"2026","description":"用 Python、Ngspice 與 SciPy 做類比電路模擬和元件尺寸搜尋，包含運算放大器、Bandgap、振盪器與 VCO。這是模擬工具；目前線上展示站無法啟動。","tags":["Python","Ngspice","sky130 PDK","SciPy","Flask"],"detail":{"purpose":"我把類比電路的模擬與調參流程整理成工具，讓使用者輸入目標後，可以比較不同元件尺寸下的模擬結果。","concept":"工具以 Ngspice 執行電路模擬，再由 SciPy 搜尋元件參數。涵蓋 AC、DC 與瞬態分析；sky130 模式使用公開 PDK。輸出是模擬結果，並非晶片實測數據。","outcome":"目前完成多種電路拓樸的模擬與參數搜尋程式。線上 Space 暫時無法使用，因此這裡不提供可操作的即時展示。","tech":[{"group":"模擬引擎","items":[{"name":"Ngspice 閉環模擬","desc":"AC/DC/瞬態自動萃取 Gain/PM/UGF、溫漂、振盪頻率；自我修復護欄偵測不收斂自動重試"},{"name":"sky130 真實 PDK","desc":"接 SkyWater sky130 開源製程（BSIM4），含 tt/ff/ss 角落，與 Level-1 快速模型雙模對照"}]},{"group":"最佳化演算法","items":[{"name":"多變量混合優化","desc":"每顆 MOS 獨立 W/L（最多 14 維），SciPy DE 全域 + Nelder-Mead 局部，多線程平行評估"},{"name":"物理護欄","desc":"強制 Wp=2~3×Wn（遷移率比）杜絕非物理解；Pelgrom 失配良率模型 σ∝1/√WL"}]},{"group":"RFIC 分析與部署","items":[{"name":"RFIC 看盤","desc":"相位雜訊（Leeson）、FTR 調諧曲線、Kvco、PVT 27 角落、帕雷托套餐、佈局 finger 拆分"},{"name":"雲端部署","desc":"Docker（apt ngspice + Flask）部署至 Hugging Face Spaces，目前線上 Space 無法啟動"}]}],"github":"https://github.com/Jcsk7049/analog-ic-studio","demo":null,"images":[{"src":"/images/analog-ic-studio/cover.png","caption":"本機 Flask 儀表板實際畫面；此次擷取只開啟介面，未執行電路最佳化。"}]},"cover":"/images/analog-ic-studio/cover.png"}', '{"id":"analog-ic-studio","category":"大學校外作品","title":"Analog IC Studio — Automated Analog IC Tuning Platform","period":"2026","description":"A Python, Ngspice, and SciPy toolkit for simulating analog circuits and searching component sizes, including op amps, bandgap references, oscillators, and VCOs. It is a simulation tool; the hosted demo is currently unavailable.","tags":["Python","Ngspice","sky130 PDK","SciPy","Flask"],"detail":{"purpose":"I organized analog simulation and tuning into a tool where users can set a target and compare simulated results for different component sizes.","concept":"Ngspice runs circuit simulations and SciPy searches component parameters. The project covers AC, DC, and transient analysis; sky130 mode uses the open PDK. Results are simulations, not silicon measurements.","outcome":"The project includes simulation and parameter-search code for several circuit topologies. The hosted Space is currently unavailable, so there is no live demo.","tech":[{"group":"Simulation Engine","items":[{"name":"Ngspice closed-loop","desc":"AC/DC/transient auto-extract Gain/PM/UGF, drift, frequency; self-healing guard retries on non-convergence"},{"name":"Real sky130 PDK","desc":"SkyWater sky130 open process (BSIM4) with tt/ff/ss corners, paired with a fast Level-1 model"}]},{"group":"Optimization","items":[{"name":"Multi-variable hybrid","desc":"Per-instance W/L (up to 14-D), SciPy DE global + Nelder-Mead local, parallel multi-threaded eval"},{"name":"Physics guard","desc":"Enforces Wp=2-3x Wn (mobility ratio); Pelgrom mismatch yield model, sigma ~ 1/sqrt(WL)"}]},{"group":"RFIC & Deployment","items":[{"name":"RFIC dashboard","desc":"Phase noise (Leeson), FTR tuning curve, Kvco, 27-corner PVT, Pareto packages, finger splitting"},{"name":"Cloud deploy","desc":"Docker (apt ngspice + Flask) on Hugging Face Spaces; currently unavailable"}]}],"github":"https://github.com/Jcsk7049/analog-ic-studio","demo":null,"images":[{"src":"/images/analog-ic-studio/cover.png","caption":"Actual local Flask dashboard; the interface was opened for this capture, without running circuit optimization."}]},"cover":"/images/analog-ic-studio/cover.png"}', '1');
INSERT OR REPLACE INTO projects (id, zh, en, sort_order) VALUES ('virtual-office', '{"id":"virtual-office","cover":"/images/virtual-office/cover.png","category":"大學校外作品","title":"Virtual Office — 桌面像素辦公室","period":"2026","description":"以 Pygame 製作的 Windows 桌面像素辦公室，依專案狀態呈現工作室與角色動態。可切換專案、點選角色查看狀態，並縮到系統匣常駐。","tags":["Python","Pygame","Windows","System Tray","State Sensors"],"detail":{"purpose":"我想在桌面快速掌握不同專案目前的狀態，因此把專案資訊整理成一個可切換的像素辦公室。","concept":"程式以 Pygame 建立七個工作室與十六個角色。專案層級的狀態感測器提供畫面資訊，使用者可切換工作室、點選角色查看動態，或將程式縮至系統匣。","outcome":"完成 Windows 桌面版的像素辦公室原型，包含工作室切換、角色狀態檢視與系統匣操作。封面截自目前執行中的每日模擬畫面。","tech":[{"group":"桌面介面","items":[{"name":"Pygame 場景","desc":"以像素工作室呈現專案和角色狀態，支援房間切換與角色互動。"},{"name":"系統匣操作","desc":"將桌面程式縮到 Windows 系統匣，方便在工作時保留狀態視圖。"}]},{"group":"狀態呈現","items":[{"name":"專案狀態感測器","desc":"由專案層級的感測器整理目前工作狀態，供工作室畫面顯示。"},{"name":"跨房間訊息","desc":"在不同工作室間呈現角色訊息，讓專案動態能在同一個桌面空間查看。"}]}],"images":[{"src":"/images/virtual-office/cover.png","caption":"本機執行中的每日模擬畫面；呈現工作室配置與角色位置。"}]}}', '{"id":"virtual-office","cover":"/images/virtual-office/cover.png","category":"大學校外作品","title":"Virtual Office — Desktop Pixel Workspace","period":"2026","description":"A Windows desktop pixel office built with Pygame. It turns project status into room and character activity, with project switching, character status views, and a system tray mode.","tags":["Python","Pygame","Windows","System Tray","State Sensors"],"detail":{"purpose":"I wanted a quick desktop view of several projects, so I organized their status into a switchable pixel office.","concept":"Built with Pygame, the app contains seven workrooms and sixteen roles. Project-level status sensors feed the scenes; users can switch rooms, inspect character activity, or minimize the app to the system tray.","outcome":"Completed a Windows desktop prototype with room switching, character status views, and system tray controls. The cover is a screenshot of the running daily simulation.","tech":[{"group":"Desktop Interface","items":[{"name":"Pygame scenes","desc":"Shows project and character status in pixel-art workrooms, with room switching and character interaction."},{"name":"System tray controls","desc":"Minimizes the desktop app to the Windows system tray for a persistent status view."}]},{"group":"Status Display","items":[{"name":"Project status sensors","desc":"Collects project-level status for display in the workroom scenes."},{"name":"Cross-room messages","desc":"Presents messages across workrooms so project activity can be viewed in one desktop space."}]}],"images":[{"src":"/images/virtual-office/cover.png","caption":"Local daily simulation showing the workroom layout and character positions."}]}}', '5');
INSERT OR REPLACE INTO projects (id, zh, en, sort_order) VALUES ('nkhs-tree-map', '{"id":"nkhs-tree-map","cover":"/images/nkhs-tree-map/cover.png","category":"大學校外作品","title":"南港高工校園樹木量測 PWA","period":"2026","description":"學生掃描樹牌 QR Code，輸入量測角度、距離與樹圍，網頁計算樹高並將紀錄存進 Google Sheets；老師可管理名單、列印 QR 標籤，並在地圖檢視樹高分布。","tags":["PWA","JavaScript","Google Apps Script","Google Sheets","QR Code"],"detail":{"purpose":"整理校園樹木的現場量測流程，讓學生用手機登記，老師能集中查看紀錄。","concept":"學生掃描樹牌 QR Code，輸入角度、距離與樹圍；前端計算樹高，再由 Apps Script 將量測資料寫入 Google Sheets。教師端另有學生名單、樹木地圖和 QR 標籤管理頁。","outcome":"前端以原生 JavaScript 製作成可安裝的 PWA，部署在 GitHub Pages；後端使用 Google Apps Script，資料存於 Google Sheets。教師專用頁需要教師 Google 帳號登入。","tech":[{"group":"手機網頁","items":[{"name":"可安裝 PWA","desc":"以手機瀏覽器開啟量測頁，支援加入主畫面；靜態前端部署在 GitHub Pages。"},{"name":"QRCode 掃描流程","desc":"從樹牌進入對應紀錄頁，學生填寫量測角度、距離與樹圍。"}]},{"group":"資料流程","items":[{"name":"樹高計算","desc":"依眼高、仰角與距離計算樹高，前端與 Apps Script 使用一致的計算規則。"},{"name":"Google Sheets 儲存","desc":"Apps Script 接收量測紀錄並寫入試算表，教師端可匯出或管理資料。"}]},{"group":"教師工具","items":[{"name":"樹木地圖","desc":"在地圖上依量測高度著色；尚未量測的樹木另有標示。"},{"name":"名單與 QR 標籤","desc":"教師登入後可管理學生名單、通行碼，並產生樹牌 QR 標籤。"}]}],"github":"https://github.com/Jcsk7049/nkhs-tree-map","demo":"https://jcsk7049.github.io/nkhs-tree-map/public/app.html","images":[{"src":"/images/nkhs-tree-map/cover.png","caption":"GitHub Pages 正式版入口畫面；教師地圖和管理頁需要教師 Google 帳號。"}]}}', '{"id":"nkhs-tree-map","cover":"/images/nkhs-tree-map/cover.png","category":"University External Project","title":"NKHS Campus Tree Measurement PWA","period":"2026","description":"Students scan a tree-tag QR code, enter measurement angle, distance, and circumference, and save calculated tree heights to Google Sheets. Teachers can manage rosters, print QR labels, and view the height map.","tags":["PWA","JavaScript","Google Apps Script","Google Sheets","QR Code"],"detail":{"purpose":"Organize on-site campus tree measurements so students can submit readings by phone and teachers can review them in one place.","concept":"Students scan a tree-tag QR code and enter the angle, distance, and circumference. The frontend calculates height, then Apps Script writes the record to Google Sheets. Teacher pages provide roster, map, and QR-label tools.","outcome":"The native JavaScript frontend is an installable PWA hosted on GitHub Pages. Google Apps Script handles the backend, with records stored in Google Sheets. Teacher-only pages require a teacher Google account.","tech":[{"group":"Mobile Web","items":[{"name":"Installable PWA","desc":"Open the measurement flow in a mobile browser and add it to the home screen; the static frontend is hosted on GitHub Pages."},{"name":"QR Measurement Flow","desc":"Scan a tree tag to open its record, then enter measurement angle, distance, and circumference."}]},{"group":"Data Flow","items":[{"name":"Tree-Height Calculation","desc":"Calculate height from eye level, angle, and distance using matching frontend and Apps Script rules."},{"name":"Google Sheets Storage","desc":"Apps Script receives measurements and writes them to a spreadsheet for teacher review and export."}]},{"group":"Teacher Tools","items":[{"name":"Tree Map","desc":"Color map markers by measured height and distinguish trees without a reading."},{"name":"Roster and QR Labels","desc":"After teacher sign-in, manage student rosters and access codes, then generate QR labels for tree tags."}]}],"github":"https://github.com/Jcsk7049/nkhs-tree-map","demo":"https://jcsk7049.github.io/nkhs-tree-map/public/app.html","images":[{"src":"/images/nkhs-tree-map/cover.png","caption":"Live GitHub Pages entry screen. The teacher map and management pages require a teacher Google account."}]}}', '13');
